import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"熱鍵與互動手勢","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/hotkeys.md","filePath":"zh-HK/user-guide/hotkeys.md","lastUpdated":1787788413000}'),a={name:"zh-HK/user-guide/hotkeys.md"};function r(s,t,n,i,g,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="熱鍵與互動手勢" tabindex="-1">熱鍵與互動手勢 <a class="header-anchor" href="#熱鍵與互動手勢" aria-label="Permalink to &quot;熱鍵與互動手勢&quot;">​</a></h1><p>Lertaro 採用鍵盤優先的互動設計，同時提供極其豐富的滑鼠快捷手勢與多級導覽系統。除固定按鍵外，所有全域與應用程式內快捷鍵均可在<a href="./settings/hotkeys-page.html"><strong>設定 → 熱鍵</strong></a>中自由重新綁定。</p><h2 id="_1-全域快捷鍵速查表" tabindex="-1">1. 全域快捷鍵速查表 <a class="header-anchor" href="#_1-全域快捷鍵速查表" aria-label="Permalink to &quot;1. 全域快捷鍵速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">功能動作</th><th style="text-align:left;">預設快捷鍵</th><th style="text-align:left;">功能說明與互動細節</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>呼出/隱藏快速視窗</strong></td><td style="text-align:left;">雙擊 <code>Ctrl</code></td><td style="text-align:left;">可設定為雙擊模式或常規組合鍵（例如 <code>Alt+Space</code>、<code>Win+Space</code> 等）。啟用「預設開啟完整面板」後，此快捷鍵會改為開啟主視窗：首次顯示時只將其置於前景並聚焦一次，視窗已顯示但未啟用時重新啟用，視窗已啟用時再次按下則關閉；不會自動保持置頂。</td></tr><tr><td style="text-align:left;"><strong>快速切換（Quick Jump）</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">在檔案對話方塊中直接跳轉到最近一次從受支援檔案管理器或快速面板中瀏覽的資料夾。</td></tr><tr><td style="text-align:left;"><strong>選取下一項</strong></td><td style="text-align:left;"><code>Ctrl+N</code> 或 <code>↓</code></td><td style="text-align:left;">向下移動列表反白項目。在快速面板中支援無縫跨分組連續瀏覽。</td></tr><tr><td style="text-align:left;"><strong>選取上一項</strong></td><td style="text-align:left;"><code>Ctrl+P</code> 或 <code>↑</code></td><td style="text-align:left;">向上移動列表反白項目。在快速面板中同樣支援跨分組巡覽。</td></tr><tr><td style="text-align:left;"><strong>跳轉至第 1–9 項結果</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">修飾鍵可自訂，快速視窗結果旁會顯示對應的數字徽章，直接按鍵秒開目標項目。</td></tr><tr><td style="text-align:left;"><strong>開啟動作選單</strong></td><td style="text-align:left;"><code>Ctrl+O</code> 或 <code>→</code></td><td style="text-align:left;">展開選取結果的快顯動作面板（複製路徑、屬性、以系統管理員身分執行、檔案操作等）。</td></tr><tr><td style="text-align:left;"><strong>從選取項補全搜尋詞</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">將當前選取項目的名稱或完整路徑直接填入搜尋框，便於在此基礎上做二次篩選。</td></tr><tr><td style="text-align:left;"><strong>QuickLook 即時預覽</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">開啟/關閉選取項目的側邊預覽面板（圖片、文件、音訊/影片即時播放、資料夾結構等）。</td></tr><tr><td style="text-align:left;"><strong>上一條搜尋記錄詞</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">向前翻閱最近輸入過的搜尋關鍵字。</td></tr><tr><td style="text-align:left;"><strong>下一條搜尋記錄詞</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">向後翻閱最近輸入過的搜尋關鍵字。</td></tr><tr><td style="text-align:left;"><strong>刪除當前歷史詞</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">從最近搜尋歷史記錄中移除當前顯示的這一條詞彙。</td></tr><tr><td style="text-align:left;"><strong>開啟完整搜尋主視窗</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">直接開啟大尺寸主搜尋視窗，並自動同步當前快速視窗中的搜尋詞。</td></tr><tr><td style="text-align:left;"><strong>開啟傳送視窗（LocalSend）</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">開啟 LocalSend 無線區域網路傳輸視窗，快速傳送檔案或文字至跨平台裝置。</td></tr><tr><td style="text-align:left;"><strong>保持視窗不消失（釘住）</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">臨時鎖定視窗，在失去焦點時不再自動隱藏（便於從其他視窗複製文字組合查詢）。</td></tr><tr><td style="text-align:left;"><strong>呼出/關閉快速面板</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">在當前前景活動視窗旁展開包含最近檔案、我的最愛、工作區的快速停靠面板。</td></tr></tbody></table><h2 id="_2-搜尋框圖示與滑鼠手勢" tabindex="-1">2. 搜尋框圖示與滑鼠手勢 <a class="header-anchor" href="#_2-搜尋框圖示與滑鼠手勢" aria-label="Permalink to &quot;2. 搜尋框圖示與滑鼠手勢&quot;">​</a></h2><p>搜尋框內的小圖示不僅是品牌識別，更集成了多種實用的滑鼠快捷手勢：</p><h3 id="快速搜尋視窗中的圖示手勢" tabindex="-1">快速搜尋視窗中的圖示手勢 <a class="header-anchor" href="#快速搜尋視窗中的圖示手勢" aria-label="Permalink to &quot;快速搜尋視窗中的圖示手勢&quot;">​</a></h3><ul><li><strong>滑鼠左鍵按一下</strong>：直接在游標處彈出快捷主選單（顯示主視窗、切換熱鍵配置、開啟設定、關於、乾淨結束、結束程式）。其中「顯示主視窗」會自動攜帶當前輸入的內容。</li><li><strong>滑鼠左鍵按住拖曳</strong>：自由拖曳調整搜尋列在螢幕上的顯示位置。<strong>拖曳時按住 <code>Ctrl</code> 鍵</strong>可將移動方向嚴格鎖定為<strong>純垂直方向</strong>，避免水平位置發生偏移。</li><li><strong>滑鼠右鍵按一下</strong>：一鍵將快速視窗重設回螢幕初始預設置中位置（不改變已配置的視窗尺寸）。</li><li><strong>滑鼠中鍵按一下</strong>：快捷切換視窗「釘住（保持不消失）」狀態，釘住期間 Logo 圖示會反白發光。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>快速視窗記錄的螢幕座標是相對於所在顯示器的<strong>相對比例座標</strong>。當你將視窗喚出在另一台不同解析度、不同 DPI 縮放的顯示器上時，Lertaro 會自動等比換算位置，絕不會跑出螢幕可視區域。</p></div><h3 id="內嵌視窗與主視窗中的圖示" tabindex="-1">內嵌視窗與主視窗中的圖示 <a class="header-anchor" href="#內嵌視窗與主視窗中的圖示" aria-label="Permalink to &quot;內嵌視窗與主視窗中的圖示&quot;">​</a></h3><ul><li><strong>內嵌視窗</strong>：當嵌入在原生檔案對話方塊（開啟/儲存/瀏覽）時，按一下左鍵圖示可直接展開<a href="#3-快速導覽滑鼠觸發"><strong>快速導覽</strong></a>級聯選單；停靠在普通檔案總管時僅作展示。</li><li><strong>主視窗</strong>：按一下左鍵圖示會開啟快顯功能表；由於主視窗已經開啟，功能表中的「顯示主視窗」項目會隱藏。按一下中鍵可切換視窗的釘住狀態。</li></ul><h2 id="_3-快速導覽-滑鼠觸發" tabindex="-1">3. 快速導覽（滑鼠觸發） <a class="header-anchor" href="#_3-快速導覽-滑鼠觸發" aria-label="Permalink to &quot;3. 快速導覽（滑鼠觸發）&quot;">​</a></h2><p>快速導覽功能讓你無需打字，透過滑鼠按一下即可在任意視窗中直達常用目錄或開啟檔案。</p><h3 id="觸發方式與支援環境" tabindex="-1">觸發方式與支援環境 <a class="header-anchor" href="#觸發方式與支援環境" aria-label="Permalink to &quot;觸發方式與支援環境&quot;">​</a></h3><ul><li><strong>桌面空白處</strong>：滑鼠中鍵按一下（或開啟按兩下左鍵）直接彈出快速導覽選單，按一下目錄或檔案直接開啟。</li><li><strong>檔案總管</strong>：在檔案總管空白處按一下滑鼠中鍵觸發，按一下目標後當前視窗立即跳轉到該路徑。</li><li><strong>第三方檔案管理器</strong>：在 Directory Opus、Total Commander、XYplorer、Files、One Commander 等工具的檔案列表區按一下滑鼠中鍵觸發（詳見<a href="./file-manager-support.html"><strong>支援的檔案管理器</strong></a>）。</li><li><strong>系統檔案對話方塊</strong>：在任意軟體的「開啟/儲存/瀏覽資料夾」對話方塊中按一下中鍵或按一下內嵌圖示觸發，按一下後對話方塊直接跳轉至目標目錄，絕不會誤觸發「儲存/開啟」確認。</li></ul><h3 id="級聯選單內容與管理" tabindex="-1">級聯選單內容與管理 <a class="header-anchor" href="#級聯選單內容與管理" aria-label="Permalink to &quot;級聯選單內容與管理&quot;">​</a></h3><p>快速導覽選單由**級聯資料夾瀏覽器（Folder Cascader）**外掛模組驅動，內容高度結構化：</p><ol><li><strong>當前開啟的資料夾</strong>：自動彙總並去重所有受支援檔案管理器當前正在瀏覽的真實目錄，方便在不同應用程式間快速同步路徑。</li><li><strong>我的最愛與歷史記錄</strong>：自動按分類列出你的加星收藏與最近造訪歷史。</li><li><strong>自訂快捷分類</strong>：支援在<strong>設定 → 外掛模組 → 級聯資料夾瀏覽器</strong>中自訂目錄與子選單（如使用 <code>工作/專案A</code> 建立多級分類）。</li><li><strong>一鍵新增目錄（<code>+</code> 按鈕）</strong>：選單每個層級的標題右側均設有一個 <code>+</code> 按鈕，按一下即可直接將當前正在瀏覽的資料夾快速儲存到該分類下，無需開啟設定面板。</li></ol><h2 id="_4-硬編碼核心按鍵-不可修改" tabindex="-1">4. 硬編碼核心按鍵（不可修改） <a class="header-anchor" href="#_4-硬編碼核心按鍵-不可修改" aria-label="Permalink to &quot;4. 硬編碼核心按鍵（不可修改）&quot;">​</a></h2><p>為了保證最核心互動的確定性與一致性，以下按鍵在任何配置下行為始終保持統一：</p><table tabindex="0"><thead><tr><th style="text-align:left;">按鍵</th><th style="text-align:left;">觸發場景</th><th style="text-align:left;">統一行為</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">結果列表</td><td style="text-align:left;">直接開啟選取的結果（檔案/目錄/程式/動作）。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">結果列表</td><td style="text-align:left;">在檔案總管中開啟並定位選取項目所在目錄。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">結果列表</td><td style="text-align:left;">以系統管理員權限啟動選取的程式或檔案。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">任意場景</td><td style="text-align:left;">若搜尋框內有文字則清空文字；若搜尋框已為空則關閉當前視窗或退出動作選單。</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">動作選單</td><td style="text-align:left;">當搜尋過濾詞已為空時，按下直接退出動作選單返回結果列表。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 方向鍵</td><td style="text-align:left;">動作選單</td><td style="text-align:left;">左箭頭返回上一級選單，右箭頭進入子選單。</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">所有 Lertaro 視窗</td><td style="text-align:left;">強制屏蔽系統標題列選單，防止誤觸彈窗。</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">主視窗 / 設定視窗</td><td style="text-align:left;">關閉當前視窗。在快速視窗、內嵌視窗及預覽浮窗上會被屏蔽（防止誤關閉駐留服務）。</td></tr></tbody></table><h2 id="_5-外掛模組動作熱鍵與處理程序黑名單" tabindex="-1">5. 外掛模組動作熱鍵與處理程序黑名單 <a class="header-anchor" href="#_5-外掛模組動作熱鍵與處理程序黑名單" aria-label="Permalink to &quot;5. 外掛模組動作熱鍵與處理程序黑名單&quot;">​</a></h2><h3 id="外掛模組獨立動作熱鍵" tabindex="-1">外掛模組獨立動作熱鍵 <a class="header-anchor" href="#外掛模組獨立動作熱鍵" aria-label="Permalink to &quot;外掛模組獨立動作熱鍵&quot;">​</a></h3><p>外掛模組可以註冊專屬動作快捷鍵（例如 <code>Ctrl+Shift+C</code> 快速複製路徑，以及內建檔案操作：剪下 <code>Ctrl+X</code>、複製 <code>Ctrl+C</code>、貼上 <code>Ctrl+V</code>、刪除 <code>Delete</code>、徹底刪除 <code>Shift+Delete</code> 等）。你可以在<strong>設定 → 熱鍵 → 外掛模組動作</strong>中統一查看並重新綁定。</p><h3 id="處理程序黑名單與全螢幕自動放行" tabindex="-1">處理程序黑名單與全螢幕自動放行 <a class="header-anchor" href="#處理程序黑名單與全螢幕自動放行" aria-label="Permalink to &quot;處理程序黑名單與全螢幕自動放行&quot;">​</a></h3><ul><li><strong>全螢幕應用程式自動放行</strong>：當偵測到前景有獨占全螢幕運行的應用程式（如全螢幕 3D 遊戲、全螢幕影片播放器）時，Lertaro 預設會自動放行所有全域快捷鍵，絕不搶佔遊戲控制。</li><li><strong>自訂處理程序黑名單</strong>：在<a href="./settings/hotkeys-page.html#process-blacklist"><strong>設定 → 熱鍵頁面</strong></a>中新增特定處理程序名稱（如 <code>game.exe</code>），當該程式處於前景時，全域熱鍵與滑鼠快速導覽將完全靜默放行。</li></ul>',26)])])}const x=e(a,[["render",r]]);export{h as __pageData,x as default};
